fn err(message:impl Into<String>)->Fault{Fault::from(message.into())}
fn key(segment:&P,value:&str)->bool{matches!(segment,P::Key(key)if key==value)}
fn resolved(expression:&Expr)->Expr{catalog::ifc2x3_resolve_type(expression).unwrap_or(expression).clone()}
fn named(name:&str)->Expr{Expr{kind:"named".into(),name:Some(name.to_ascii_uppercase()),..Default::default()}}
fn accepts(expression:&Expr,name:&str)->bool{let expression=resolved(expression);expression.name.as_ref().is_some_and(|expected|catalog::ifc2x3_is_subtype(name,expected)||catalog::ifc2x3_select_accepts(expected,name))}
fn leaves(expression:&Expr,depth:usize,result:&mut std::collections::BTreeSet<String>){if depth>=64{return;}let Some(name)=expression.name.as_ref()else{return};if let Some(members)=catalog::ifc2x3_select_members(name){for member in members{leaves(&named(member),depth+1,result);}}else{result.insert(name.to_ascii_uppercase());}}
fn reference(expression:&Expr)->bool{let mut members=Default::default();leaves(expression,0,&mut members);members.iter().any(|name|catalog::ifc2x3_catalog().entities.contains_key(name))}
struct Context<'a>{instance:&'a Part21Instance,attribute:Attr,expression:Expr,value:&'a V,payload:bool}
pub struct Ifc2x3DetailsProvider<'a>{snapshot:&'a Ifc2x3Snapshot,raw:DslSnapshotDetailsProvider<'a,Ifc2x3Snapshot>}
impl<'a> Ifc2x3DetailsProvider<'a>{
    pub fn new(snapshot:&'a Ifc2x3Snapshot)->Self{Self{snapshot,raw:DslSnapshotDetailsProvider::new(snapshot)}}
    fn entity(&self,path:&[P])->Option<(&'a Part21Instance,usize)>{let [P::Key(document),P::Key(instances),P::Index(row),P::Key(entities),P::Index(part)]=path else{return None};if document!="document"||instances!="instances"||entities!="entities"{return None;}let instance=self.snapshot.document.instances.get(*row)?;instance.entities.get(*part)?;Some((instance,*part))}
    fn context(&self,path:&[P])->Option<Context<'a>>{if path.len()<7||path.len()>128||!key(&path[5],"arguments"){return None;}let (instance,part)=self.entity(&path[..5])?;let (name,args)=&instance.entities[part];let P::Index(index)=path[6]else{return None};let declaration=catalog::ifc2x3_catalog().entities.get(&name.to_ascii_uppercase())?;let attrs=if instance.entities.len()==1{&declaration.all_attributes}else{&declaration.attributes};let mut attribute=attrs.get(index)?.clone();if instance.entities.iter().any(|(name,_)|catalog::ifc2x3_catalog().entities.get(&name.to_ascii_uppercase()).is_some_and(|declaration|declaration.all_attributes.iter().any(|other|other.derived&&other.name==attribute.name&&other.declared_by==attribute.declared_by))){attribute.derived=true;}let mut expression=attribute.type_expr.clone();let mut value=args.get(index)?;let mut cursor=7;let mut payload=false;while cursor<path.len(){let field=&path[cursor];cursor+=1;if key(field,"reference")||key(field,"appendReference"){if cursor==path.len(){break;}return None;}if key(field,"value"){payload=true;if cursor==path.len()||matches!(value,V::Real(_)){break;}return None;}if !key(field,"values"){return None;}if cursor==path.len(){payload=true;if let V::Typed{name,..}=value{expression=named(name);}break;}let P::Index(index)=path[cursor]else{return None};cursor+=1;value=match value{V::List(items)=>{let aggregate=resolved(&expression);expression=*aggregate.item?;expression.optional|=aggregate.optional;items.get(index)?},V::Typed{name,items}=>{expression=named(name);items.get(index)?},_=>return None};payload=false;}Some(Context{instance,attribute,expression,value,payload})}
    fn slot(&self,path:&[P])->bool{self.context(path).is_some_and(|context|!context.attribute.derived&&!context.payload&&reference(&context.expression))}
    fn collection(&self,path:&[P])->Option<(Expr,&'a[V])>{let context=self.context(path)?;let V::List(items)=context.value else{return None};let expression=resolved(&context.expression);if context.payload||context.attribute.derived||expression.aggregate.as_deref()==Some("ARRAY")||expression.upper.is_some_and(|upper|items.len()>=upper.max(0)as usize)||!reference(expression.item.as_deref()?){return None;}Some((expression,items))}
    fn template(&self,expression:&Expr,depth:usize)->Option<V>{self.template_controlled(expression,depth,&mut ||Ok(())).ok().flatten()}
    fn template_controlled(&self,expression:&Expr,depth:usize,tick:&mut dyn FnMut()->Result<(),String>)->Result<Option<V>,Fault>{
        tick().map_err(err)?;if depth>=64{return Ok(None);}let expression=resolved(expression);
        if expression.kind=="aggregate"{let count=if expression.aggregate.as_deref()==Some("ARRAY"){let (Some(upper),Some(lower))=(expression.upper,expression.lower)else{return Ok(None)};let Some(count)=upper.checked_sub(lower).and_then(|count|count.checked_add(1))else{return Ok(None)};count.max(0)as usize}else{expression.lower.unwrap_or(0).max(0)as usize};if count>256||expression.unique&&count>1{return Ok(None);}if count==0{return Ok(Some(V::List(Vec::new())));}let Some(item)=expression.item.as_deref()else{return Ok(None)};let Some(value)=self.template_controlled(item,depth+1,tick)?else{return Ok(None)};let mut values=Vec::new();for _ in 0..count{tick_value(&value,tick,0)?;values.push(value.clone());}return Ok(Some(V::List(values)));}
        let Some(name)=expression.name.as_ref().map(|name|name.to_ascii_uppercase())else{return Ok(None)};
        if catalog::ifc2x3_catalog().entities.contains_key(&name){for instance in self.snapshot.document.instances.iter().take(256){tick().map_err(err)?;for (name,_)in &instance.entities{tick().map_err(err)?;if accepts(&expression,name){return Ok(Some(V::Ref(instance.id)));}}}return Ok(None);}
        if let Some(declaration)=catalog::ifc2x3_catalog().types.get(&name){if declaration.kind=="enum"{return Ok(declaration.members.first().map(|member|V::Enum(member.clone())));}if declaration.kind=="select"{for member in &declaration.members{tick().map_err(err)?;if let Some(value)=self.template_controlled(&named(member),depth+1,tick)?{return Ok(Some(if matches!(value,V::Ref(_)|V::Typed{..}){value}else{V::Typed{name:member.clone(),items:vec![value]}}));}}return Ok(None);}return Ok(None);}
        Ok(match name.as_str(){"STRING"=>Some(V::Str(String::new())),"BINARY"=>Some(V::Binary("0".into())),"INTEGER"=>Some(V::Int(0)),"REAL"|"NUMBER"=>Some(V::Real(Part21Decimal::from_f64(0.0))),"BOOLEAN"|"LOGICAL"=>Some(V::Enum("F".into())),_=>None})
    }
    fn alternatives(&self,path:&[P],locale:Locale)->Vec<SnapshotDetailVariant>{if let Some((instance,_))=self.entity(path){return catalog::ifc2x3_catalog().entities.values().filter(|entity|instance.entities.len()>1||!entity.abstract_entity).map(|entity|SnapshotDetailVariant{label:entity.name.clone(),value:DslValue::Object(vec![("$ifcType".into(),DslValue::String(entity.name.clone()))])}).collect();}let Some(context)=self.context(path)else{return Vec::new()};if context.payload||context.attribute.derived{return Vec::new();}let mut variants=Vec::new();if context.expression.optional||context.attribute.optional&&path.len()==7{variants.push(SnapshotDetailVariant{label:match locale{Locale::En=>"Unset ($)",Locale::De=>"Nicht gesetzt ($)"}.into(),value:V::Unset.to_value()});}if matches!(context.value,V::Unset){if let Some(value)=self.template(&context.expression,0){variants.push(SnapshotDetailVariant{label:match locale{Locale::En=>"Create value",Locale::De=>"Wert erstellen"}.into(),value:value.to_value()});}}let expression=resolved(&context.expression);if expression.name.as_ref().is_some_and(|name|catalog::ifc2x3_select_members(name).is_some()){let mut members=Default::default();leaves(&expression,0,&mut members);for member in members{if let Some(value)=self.template(&named(&member),0){let value=if matches!(value,V::Ref(_)|V::Typed{..}){value}else{V::Typed{name:member.clone(),items:vec![value]}};variants.push(SnapshotDetailVariant{label:member,value:value.to_value()});}}}variants}
}
impl SnapshotDetailsProvider for Ifc2x3DetailsProvider<'_>{
    fn value(&self,path:&[P])->Option<SnapshotDetailValue>{if let Some((P::Key(field),parent))=path.split_last(){if field=="reference"&&self.slot(parent){let context=self.context(parent)?;return Some(SnapshotDetailValue::String(context.value.as_ref_id().map_or_else(String::new,|id|id.to_string())));}if field=="appendReference"&&self.collection(parent).is_some(){return Some(SnapshotDetailValue::String(String::new()));}}if let Some(Context{value:V::Ref(id),payload:true,..})=self.context(path){return Some(SnapshotDetailValue::String(id.to_string()));}self.raw.value(path)}
    fn child_count(&self,path:&[P])->usize{if let Some(context)=self.context(path){if !context.payload{if self.slot(path){return 1;}return usize::from(!matches!(context.value,V::Unset|V::Derived))+usize::from(self.collection(path).is_some());}}self.raw.child_count(path)}
    fn object_key(&self,path:&[P],index:usize)->Option<String>{if let Some(context)=self.context(path){if !context.payload{if self.slot(path){return (index==0).then(||"reference".into());}let payload=usize::from(!matches!(context.value,V::Unset|V::Derived));if index==0&&payload==1{return Some(if matches!(context.value,V::List(_)|V::Typed{..}){"values"}else{"value"}.into());}if index==payload&&self.collection(path).is_some(){return Some("appendReference".into());}return None;}}self.raw.object_key(path,index)}
    fn has_source(&self)->bool{true}
    fn source(&self)->Option<String>{self.raw.source()}
    fn allows_untyped_creation(&self,_path:&[P])->bool{false}
    fn enum_values(&self,path:&[P])->Vec<DslValue>{let Some(context)=self.context(path)else{return Vec::new()};if !context.payload||!matches!(context.value,V::Enum(_)){return Vec::new();}let expression=resolved(&context.expression);let Some(name)=expression.name else{return Vec::new()};let members=if name=="BOOLEAN"{vec!["T".into(),"F".into()]}else if name=="LOGICAL"{vec!["T".into(),"F".into(),"U".into()]}else{catalog::ifc2x3_enum_members(&name).map(<[String]>::to_vec).unwrap_or_default()};members.into_iter().map(DslValue::String).collect()}
    fn presentation(&self,path:&[P],locale:Locale)->Option<SnapshotDetailPresentation>{if let Some(context)=self.context(path){if !context.payload{return Some(SnapshotDetailPresentation{label:context.attribute.name,description:Some(match locale{Locale::En=>format!("{} · {} · IFC2x3 TC1",context.attribute.declared_by,context.expression.name.as_deref().or(context.expression.aggregate.as_deref()).unwrap_or("")),Locale::De=>format!("{} · {} · IFC2x3 TC1",context.attribute.declared_by,context.expression.name.as_deref().or(context.expression.aggregate.as_deref()).unwrap_or(""))})});}}if let Some((instance,index))=self.entity(path){return Some(SnapshotDetailPresentation{label:format!("#{} {}",instance.id,instance.entities[index].0),description:None});}None}
    fn item_capabilities(&self,path:&[P])->SnapshotDetailItemCapabilities{let mut result=SnapshotDetailItemCapabilities{edit:false,rename:false,remove:false,reorder:false};if let Some((P::Key(field),parent))=path.split_last(){if field=="reference"&&self.slot(parent)||field=="appendReference"&&self.collection(parent).is_some(){result.edit=true;return result;}}if let Some(context)=self.context(path){result.edit=context.payload&&!context.attribute.derived&&!matches!(context.value,V::List(_)|V::Typed{..});if matches!(path.last(),Some(P::Index(_)))&&path.len()>7{if let Some(parent)=self.context(&path[..path.len()-1]){if let V::List(items)=parent.value{let domain=resolved(&parent.expression);result.remove=!context.attribute.derived&&domain.aggregate.as_deref()!=Some("ARRAY")&&items.len()>domain.lower.unwrap_or(0).max(0)as usize;result.reorder=!context.attribute.derived&&matches!(domain.aggregate.as_deref(),Some("LIST")|Some("ARRAY"));}}}return result;}if path.starts_with(&[P::Key("document".into()),P::Key("header".into())]){result.edit=!matches!(path.last(),Some(P::Key(field))if field=="kind");}if path.len()==3&&key(&path[0],"document")&&key(&path[1],"instances"){result.remove=true;}result}
    fn allows_collection_insert(&self,path:&[P])->bool{let Some(context)=self.context(path)else{return false};let V::List(items)=context.value else{return false};let domain=resolved(&context.expression);context.payload&&!context.attribute.derived&&domain.aggregate.as_deref()!=Some("ARRAY")&&domain.upper.is_none_or(|upper|items.len()<upper.max(0)as usize)&&self.creation_template(path,true).is_some()}
    fn creation_template(&self,path:&[P],collection_item:bool)->Option<DslValue>{let context=self.context(path)?;if context.attribute.derived{return None;}let expression=resolved(&context.expression);let value=if collection_item{let V::List(items)=context.value else{return None};let value=self.template(expression.item.as_deref()?,0)?;if (expression.unique||expression.aggregate.as_deref()==Some("SET"))&&items.contains(&value){return None;}value}else{self.template(&expression,0)?};Some(value.to_value())}
    fn variants(&self,path:&[P],locale:Locale)->Vec<SnapshotDetailVariant>{self.alternatives(path,locale)}
    fn variant_count(&self,path:&[P],locale:Locale)->usize{if let Some((instance,_))=self.entity(path){return catalog::ifc2x3_catalog().entities.values().filter(|entity|instance.entities.len()>1||!entity.abstract_entity).count();}self.alternatives(path,locale).len()}
    fn variant(&self,path:&[P],locale:Locale,index:usize)->Option<SnapshotDetailVariant>{if let Some((instance,_))=self.entity(path){let entity=catalog::ifc2x3_catalog().entities.values().filter(|entity|instance.entities.len()>1||!entity.abstract_entity).nth(index)?;return Some(SnapshotDetailVariant{label:entity.name.clone(),value:DslValue::Object(vec![("$ifcType".into(),DslValue::String(entity.name.clone()))])});}self.alternatives(path,locale).into_iter().nth(index)}
}

