fn tick_value(value:&V,tick:&mut dyn FnMut()->Result<(),String>,depth:usize)->Result<(),Fault>{tick().map_err(err)?;if depth>128{return Err(err("IFC2x3 value exceeds bounded depth"));}match value{V::Str(text)|V::Enum(text)|V::Binary(text)=>for _ in text.as_bytes().chunks(256){tick().map_err(err)?;},V::Real(decimal)=>for _ in decimal.coefficient.as_bytes().chunks(256){tick().map_err(err)?;},V::List(items)|V::Typed{items,..}=>for value in items{tick_value(value,tick,depth+1)?;},_=>{}}Ok(())}
fn tick_instance(instance:&Part21Instance,tick:&mut dyn FnMut()->Result<(),String>)->Result<(),Fault>{for (_,args)in &instance.entities{tick().map_err(err)?;for value in args{tick_value(value,tick,0)?;}}Ok(())}
fn parse_id(decimal:&str)->Result<u64,Fault>{if decimal.is_empty()||decimal.len()>20||!decimal.bytes().all(|byte|byte.is_ascii_digit()){return Err(err("IFC reference requires an exact positive u64 decimal"));}decimal.parse::<u64>().ok().filter(|id|*id>0).ok_or_else(||err("IFC reference is outside positive u64"))}
fn detail_path(path:&str)->Result<Vec<P>,Fault>{let segments=editing::decode_pointer(path).map_err(|error|err(error.to_string()))?;if segments.len()>128{return Err(err("IFC2x3 edit path exceeds bounded depth"));}Ok(segments.into_iter().map(|segment|segment.parse::<usize>().map_or_else(|_|P::Key(segment.clone()),P::Index)).collect())}
fn normalized_reference_edit(event:&SnapshotEditEvent,snapshot:&Ifc2x3Snapshot,check_target:bool,tick:&mut dyn FnMut()->Result<(),String>)->Result<Option<SnapshotEditEvent>,Fault>{tick().map_err(err)?;let SnapshotEditEvent::SetValue{path,value}=event else{return Ok(None)};let path_segments=detail_path(path)?;let provider=Ifc2x3DetailsProvider::new(snapshot);if let Some(context)=provider.context(&path_segments){if context.attribute.derived{return Err(err("Derived IFC2x3 attributes are read only"));}if !context.payload&&reference(&context.expression){if let Ok(reference@V::Ref(_)|reference@V::Unset)=V::from_value(value.clone()){let text=reference.as_ref_id().map_or_else(String::new,|id|id.to_string());return normalized_reference_edit(&SnapshotEditEvent::SetValue{path:format!("{path}/reference"),value:DslValue::String(text)},snapshot,check_target,tick);}}}let Some((P::Key(field),parent))=path_segments.split_last()else{return Ok(None)};let append=field=="appendReference";let virtual_slot=field=="reference";let context=if append{if provider.collection(parent).is_none(){return Ok(None);}provider.context(parent)}else if virtual_slot{if !provider.slot(parent){return Ok(None);}provider.context(parent)}else{provider.context(&path_segments).filter(|context|context.payload&&matches!(context.value,V::Ref(_)))};let Some(context)=context else{return Ok(None)};let DslValue::String(text)=value else{return Err(err("IFC reference field requires exact decimal text"))};let id=if virtual_slot&&text.is_empty(){None}else{Some(parse_id(text)?)};if id.is_none()&&!(context.expression.optional||context.attribute.optional&&parent.len()==7){return Err(err("Required IFC2x3 reference cannot be unset"));}if check_target{if let Some(id)=id{let expression=if append{*resolved(&context.expression).item.ok_or_else(||err("IFC reference collection has no item type"))?}else{context.expression.clone()};let mut admitted=false;for instance in &snapshot.document.instances{tick().map_err(err)?;if instance.id==id{for (name,_)in &instance.entities{tick().map_err(err)?;if accepts(&expression,name){admitted=true;break;}}break;}}if !admitted{return Err(err("IFC2x3 reference target does not have an admitted entity type"));}if append{let (expression,items)=provider.collection(parent).ok_or_else(||err("IFC2x3 reference collection has no capacity"))?;if expression.unique||expression.aggregate.as_deref()==Some("SET"){for value in items{tick().map_err(err)?;if value==&V::Ref(id){return Err(err("IFC2x3 reference duplicates a SET or UNIQUE target"));}}}}}}if check_target&&!append{if let Some(id)=id{for cursor in 7..path_segments.len().saturating_sub(1){tick().map_err(err)?;if !key(&path_segments[cursor],"values"){continue;}let Some(P::Index(edited))=path_segments.get(cursor+1)else{continue};let Some(parent)=provider.context(&path_segments[..cursor])else{continue};let V::List(items)=parent.value else{continue};let expression=resolved(&parent.expression);if expression.unique||expression.aggregate.as_deref()==Some("SET"){for (index,value)in items.iter().enumerate(){tick().map_err(err)?;if index!=*edited&&value==&V::Ref(id){return Err(err("IFC2x3 reference duplicates a SET or UNIQUE target"));}}}}}}let parent=path.rsplit_once('/').map_or("",|(parent,_)|parent);let value=id.map_or(V::Unset,V::Ref);Ok(Some(if append{SnapshotEditEvent::InsertValue{path:format!("{parent}/values/-"),value:value.to_value()}}else if virtual_slot{SnapshotEditEvent::SetValue{path:parent.into(),value:value.to_value()}}else{SnapshotEditEvent::SetValue{path:path.clone(),value:DslValue::uint(id.expect("direct reference is present"))}}))}
fn requested_type(value:&DslValue)->Option<&str>{let DslValue::Object(fields)=value else{return None};let [(key,DslValue::String(name))]=fields.as_slice()else{return None};(key=="$ifcType").then_some(name.as_str())}
fn fresh_global_id(snapshot:&Ifc2x3Snapshot,id:u64,tick:&mut dyn FnMut()->Result<(),String>)->Result<String,Fault>{let mut occupied=std::collections::BTreeSet::new();for instance in &snapshot.document.instances{tick().map_err(err)?;for (_,args)in &instance.entities{tick().map_err(err)?;if let Some(V::Str(value))=args.first(){occupied.insert(value.as_str());}}}loop{tick().map_err(err)?;let guid=identity::random_global_id(id);if !occupied.contains(guid.as_str()){return Ok(guid);}}}
fn type_switch(event:&SnapshotEditEvent,snapshot:&Ifc2x3Snapshot,tick:&mut dyn FnMut()->Result<(),String>)->Result<Option<Vec<Ifc2x3Mutation>>,Fault>{let SnapshotEditEvent::SetValue{path,value}=event else{return Ok(None)};let segments=detail_path(path)?;let (entity_path,name)=if segments.len()==5{(&segments[..],requested_type(value))}else if segments.len()==6&&key(&segments[5],"typeName"){(&segments[..5],match value{DslValue::String(name)=>Some(name.as_str()),_=>None})}else{return Ok(None)};let Some(name)=name else{return Ok(None)};let provider=Ifc2x3DetailsProvider::new(snapshot);let Some((instance,index))=provider.entity(entity_path)else{return Ok(None)};let name=name.to_ascii_uppercase();let declaration=catalog::ifc2x3_catalog().entities.get(&name).ok_or_else(||err("Unknown IFC2x3 entity type"))?;let partial=instance.entities.len()>1;if declaration.abstract_entity&&!partial{return Err(err("Abstract IFC2x3 entity requires a complex instance"));}let previous=catalog::ifc2x3_catalog().entities.get(&instance.entities[index].0.to_ascii_uppercase()).ok_or_else(||err("Unknown current IFC2x3 entity type"))?;let attributes=if partial{&declaration.attributes}else{&declaration.all_attributes};let previous=if partial{&previous.attributes}else{&previous.all_attributes};tick_instance(instance,tick)?;let mut next=instance.clone();let mut arguments=Vec::new();for attribute in attributes{tick().map_err(err)?;let old=previous.iter().position(|old|old.name==attribute.name&&old.type_expr==attribute.type_expr).and_then(|position|instance.entities[index].1.get(position));let value=if attribute.derived{V::Derived}else if let Some(value)=old.filter(|value|!matches!(value,V::Derived)&&(!matches!(value,V::Unset)||attribute.optional)){value.clone()}else if attribute.optional{V::Unset}else if attribute.name=="GlobalId"{V::Str(fresh_global_id(snapshot,instance.id,tick)?)}else{provider.template_controlled(&attribute.type_expr,0,tick)?.unwrap_or(V::Unset)};arguments.push(value);}next.entities[index]=(name,arguments);let mut derived=std::collections::BTreeSet::new();for (name,_)in &next.entities{tick().map_err(err)?;if let Some(declaration)=catalog::ifc2x3_catalog().entities.get(&name.to_ascii_uppercase()){for attribute in &declaration.all_attributes{if attribute.derived{derived.insert((attribute.declared_by.as_str(),attribute.name.as_str()));}}}}if partial{for (name,args)in &mut next.entities{tick().map_err(err)?;if let Some(declaration)=catalog::ifc2x3_catalog().entities.get(&name.to_ascii_uppercase()){for (attribute,value)in declaration.attributes.iter().zip(args){tick().map_err(err)?;if attribute.derived||derived.contains(&(attribute.declared_by.as_str(),attribute.name.as_str())){*value=V::Derived;}else if matches!(value,V::Derived){*value=if attribute.optional{V::Unset}else{provider.template_controlled(&attribute.type_expr,0,tick)?.unwrap_or(V::Unset)};}}}}}Ok(Some(vec![Ifc2x3Mutation::UpsertInstance(semio_s_artifact_stdio_ifc_2x3_base_mutations::standards::v2x3::subsets::base::schema::mutations::upsert_instance::UpsertInstance{instance:next,index:None})]))}
pub fn details_edit_is_admitted(event:&SnapshotEditEvent,snapshot:&Ifc2x3Snapshot)->bool{if protocol::OpBinary::encode_op(event).map_or(true,|bytes|bytes.len()>editing::SNAPSHOT_EDIT_MAXIMUM_RAW_BYTES){return false;}match normalized_reference_edit(event,snapshot,false,&mut ||Ok(())){Ok(Some(event))=>editing::snapshot_edit_value_is_admitted(&event,snapshot),Ok(None)=>editing::snapshot_edit_value_is_admitted(event,snapshot),Err(_)=>false}}
fn plan_details_edit_special_controlled(event:&SnapshotEditEvent,snapshot:&Ifc2x3Snapshot,tick:&mut dyn FnMut()->Result<(),String>)->Result<Option<Vec<Ifc2x3Mutation>>,Fault>{tick().map_err(err)?;if let Some(mutations)=type_switch(event,snapshot,tick)?{return Ok(Some(mutations));}let normalized=normalized_reference_edit(event,snapshot,true,tick)?;let event=normalized.as_ref().unwrap_or(event);let path=match event{SnapshotEditEvent::SetValue{path,..}|SnapshotEditEvent::InsertValue{path,..}|SnapshotEditEvent::RemoveValue{path}|SnapshotEditEvent::MoveValue{path,..}|SnapshotEditEvent::RenameKey{path,..}=>Some(path),_=>None};if let Some(path)=path{let parts=detail_path(path)?;if parts.len()>3&&key(&parts[0],"document")&&key(&parts[1],"instances"){let P::Index(row)=parts[2]else{return Err(err("Invalid IFC2x3 instance position"))};let instance=snapshot.document.instances.get(row).ok_or_else(||err("IFC2x3 instance does not exist"))?;tick_instance(instance,tick)?;let next=editing::edited_subtree(&instance.to_value(),&format!("/document/instances/{row}"),event).map_err(|error|err(error.to_string()))?;let next=Part21Instance::from_value(next).map_err(|error|err(error.to_string()))?;if next.id==instance.id{return Ok(Some(vec![Ifc2x3Mutation::UpsertInstance(semio_s_artifact_stdio_ifc_2x3_base_mutations::standards::v2x3::subsets::base::schema::mutations::upsert_instance::UpsertInstance{instance:next,index:None})]));}}}if let Some(mutations)=edit_rules::special(event,snapshot).map_err(|error|err(error.to_string()))?{return Ok(Some(mutations));}edit_rules::EDIT_RULES.resolve::<Ifc2x3Snapshot,Ifc2x3Mutation>(snapshot,event).map(Some).map_err(|error|err(error.to_string()))}
pub fn details_edit_special_controlled(event:&SnapshotEditEvent,snapshot:&Ifc2x3Snapshot,tick:&mut dyn FnMut()->Result<(),String>)->Result<Option<Vec<Ifc2x3Mutation>>,Fault>{let mutations=plan_details_edit_special_controlled(event,snapshot,tick)?;if let Some(mutations)=mutations.as_deref(){let normalized=normalized_reference_edit(event,snapshot,true,tick)?;domain_edit::check(normalized.as_ref().unwrap_or(event),snapshot,mutations,tick)?;}Ok(mutations)}
